import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.util.Base64;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;

public class TestAbaQr {
    public static void main(String[] args) throws Exception {
        // Just mocking the logic to see if it compiles and the regex works
        String url = "https://checkout-sandbox.payway.com.";
        String base64 = url.substring(url.lastIndexOf('/') + 1);
        String json = new String(Base64.getDecoder().decode(base64), StandardCharsets.UTF_8);
        Matcher m = Pattern.compile("\"qr_string\"\\s*:\\s*\"([^\"]+)\"").matcher(json);
        if (m.find()) {
            System.out.println("Found QR: " + m.group(1));
        } else {
            System.out.println("QR not found in JSON");
        }
    }
}
